### 2. Component Implementation Skeletons

#### `src/modules/kudos/prisma.service.ts`
Establishes connection mapping using standard NestJS Lifecycles.
```typescript
import { Injectable, OnModuleInit } from "@nestjs/common";
import { PrismaClient } from "@prisma/client";

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit {
  async onModuleInit() {
    await this.$connect();
  }
}
```

#### `src/modules/kudos/kudos.service.ts`
Interacts with the database, handling query formatting and insertion.
```typescript
import { Injectable } from "@nestjs/common";
import { PrismaService } from "./prisma.service";
import { Kudos } from "@prisma/client";

@Injectable()
export class KudosService {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: { sender: string; recipient: string; message: string }): Promise<Kudos> {
    return this.prisma.kudos.create({
      data: {
        sender: data.sender,
        recipient: data.recipient,
        message: data.message,
      },
    });
  }

  async findAll(): Promise<Kudos[]> {
    return this.prisma.kudos.findMany({
      orderBy: [
        { createdAt: "desc" },
        { id: "desc" },
      ],
    });
  }
}
```

#### `src/modules/kudos/kudos.controller.ts`
Enforces input validation constraints and maps router handlers to responses.
```typescript
import { Controller, Get, Post, Body, BadRequestException, HttpCode, HttpStatus } from "@nestjs/common";
import { KudosService } from "./kudos.service";
import { Kudos } from "@prisma/client";

@Controller("kudos")
export class KudosController {
  constructor(private readonly kudosService: KudosService) {}

  @Post()
  @HttpCode(HttpStatus.CREATED)
  async create(@Body() body: any): Promise<Kudos> {
    if (!body) {
      throw new BadRequestException("Request body is missing.");
    }

    const { sender, recipient, message } = body;

    // Check missing
    if (sender === undefined || sender === null ||
        recipient === undefined || recipient === null ||
        message === undefined || message === null) {
      throw new BadRequestException("sender, recipient, and message fields are required.");
    }

    // Check type
    if (typeof sender !== "string" || typeof recipient !== "string" || typeof message !== "string") {
      throw new BadRequestException("sender, recipient, and message must be strings.");
    }

    // Trim and validate empty
    const trimmedSender = sender.trim();
    const trimmedRecipient = recipient.trim();
    const trimmedMessage = message.trim();

    if (trimmedSender.length === 0 || trimmedRecipient.length === 0 || trimmedMessage.length === 0) {
      throw new BadRequestException("Fields cannot be whitespace-only.");
    }

    // Check length boundaries
    if (trimmedSender.length > 50) {
      throw new BadRequestException("sender must not exceed 50 characters.");
    }
    if (trimmedRecipient.length > 50) {
      throw new BadRequestException("recipient must not exceed 50 characters.");
    }
    if (trimmedMessage.length > 500) {
      throw new BadRequestException("message must not exceed 500 characters.");
    }

    return this.kudosService.create({
      sender: trimmedSender,
      recipient: trimmedRecipient,
      message: trimmedMessage,
    });
  }

  @Get()
  async get(): Promise<Kudos[]> {
    return this.kudosService.findAll();
  }
}
```

#### `src/modules/kudos/kudos.module.ts`
Bridges controllers and providers.
```typescript
import { Module } from "@nestjs/common";
import { KudosController } from "./kudos.controller";
import { KudosService } from "./kudos.service";
import { PrismaService } from "./prisma.service";

@Module({
  controllers: [KudosController],
  providers: [KudosService, PrismaService],
})
export class KudosModule {}
```

### 3. Module Registration in `src/modules/index.ts`
Registers exactly `1` module inside the array list. This updates `GET /health` to report `modules_registered: 1` automatically (AC-9, [health.controller.ts](file:///harness/runs/kudos-wall/claude-code--gemini35-plus-25-flash-high/2026-07-26T06-37-07/workdir/src/platform/health.controller.ts#L18)).

```typescript
import { KudosModule } from "./kudos/kudos.module";

export const MODULES: any[] = [KudosModule];
```

### 4. Spec Files Layout under `test/modules/kudos.spec.ts`
Provides exhaustive test coverages using Vitest and `@nestjs/testing`:

```typescript
import { Test, TestingModule } from "@nestjs/testing";
import { describe, expect, it, beforeEach, beforeAll, afterAll } from "vitest";
import { KudosController } from "../../src/modules/kudos/kudos.controller";
import { KudosService } from "../../src/modules/kudos/kudos.service";
import { PrismaService } from "../../src/modules/kudos/prisma.service";
import { BadRequestException } from "@nestjs/common";

describe("Kudos Feature Integration & Validation Specs", () => {
  let controller: KudosController;
  let service: KudosService;
  let prisma: PrismaService;

  beforeAll(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [KudosController],
      providers: [KudosService, PrismaService],
    }).compile();

    controller = module.get<KudosController>(KudosController);
    service = module.get<KudosService>(KudosService);
    prisma = module.get<PrismaService>(PrismaService);
    await prisma.onModuleInit();
  });

  beforeEach(async () => {
    // Clean database before each spec
    await prisma.kudos.deleteMany({});
  });

  afterAll(async () => {
    await prisma.$disconnect();
  });

  describe("POST /kudos - Creation & Validation", () => {
    it("AC-1, AC-4: success response returns trimmed fields and correct ID", async () => {
      const payload = {
        sender: "   Jane Doe   ",
        recipient: "   John Smith   ",
        message: "   Exceptional work!   "
      };
      const result = await controller.create(payload);

      expect(result.id).toBeDefined();
      expect(result.sender).toBe("Jane Doe");
      expect(result.recipient).toBe("John Smith");
      expect(result.message).toBe("Exceptional work!");
      expect(result.createdAt).toBeDefined();
      expect(typeof result.createdAt).toBe("object"); // Date object from prisma
    });

    it("AC-2: fails on missing field", async () => {
      await expect(controller.create({
        sender: "Bob",
        recipient: "Alice"
      })).rejects.toThrow(BadRequestException);
    });

    it("AC-3: fails on whitespace-only fields", async () => {
      await expect(controller.create({
        sender: "   ",
        recipient: "Alice",
        message: "Work done"
      })).rejects.toThrow(BadRequestException);
    });

    it("fails on non-string inputs", async () => {
      await expect(controller.create({
        sender: 12345,
        recipient: "Alice",
        message: "Work done"
      })).rejects.toThrow(BadRequestException);
    });

    it("AC-5: fails on over-length fields", async () => {
      const overLengthMessage = "a".repeat(501);
      await expect(controller.create({
        sender: "Bob",
        recipient: "Alice",
        message: overLengthMessage
      })).rejects.toThrow(BadRequestException);
    });
  });

  describe("GET /kudos - Ordering and Tiebreaking", () => {
    it("AC-6, AC-7: returns ordered records and correctly resolves ties via id descending", async () => {
      // Create test items with fixed sequence
      const k1 = await service.create({ sender: "S1", recipient: "R1", message: "M1" });
      const k2 = await service.create({ sender: "S2", recipient: "R2", message: "M2" });

      const results = await controller.get();

      expect(results.length).toBe(2);
      // Newest should be returned first (k2 followed by k1)
      expect(results[0].id).toBe(k2.id);
      expect(results[1].id).toBe(k1.id);
    });
  });
});
```
